local PenRestMaker = {}
local PRODUCTS = {
    iron_penrest = { name = "Železni počivališče za peresa", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni počivališče za peresa za pisarje." },
    bronze_penrest = { name = "Bronast počivališče za peresa", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast počivališče za peresa za pisarje." },
    silver_penrest = { name = "Srebrn počivališče za peresa", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn počivališče za peresa za pisarje." },
    gilded_penrest = { name = "Pozlačen počivališče za peresa", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen počivališče za peresa za pisarje." },
    jewel_set_penrest = { name = "Draguljast počivališče za peresa", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast počivališče za peresa za pisarje." },
    royal_sovereign_penrest = { name = "Kraljevski suveren počivališče za peresa", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren počivališče za peresa z biseri za krono." },
}
local BUILDINGS = {
    penrest_workshop = { name = "Penrest delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    penrest_house = { name = "Penrest hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_penrest_atelier = { name = "Mojstrski penrest atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_penrest_palace = { name = "Suverena penrest palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PenRestMaker.ironStock=14; PenRestMaker.bronzeStock=12; PenRestMaker.woodStock=14; PenRestMaker.leatherStock=8; PenRestMaker.silverStock=8; PenRestMaker.goldStock=6; PenRestMaker.jewelStock=4; PenRestMaker.pearlStock=4
PenRestMaker.productStock = {}; PenRestMaker.buildings = {}; PenRestMaker.maker = nil; PenRestMaker.activeMaking = {}; PenRestMaker.totalProducts = 0; PenRestMaker.dayTimer = 0
function PenRestMaker.init() PenRestMaker.ironStock=14; PenRestMaker.bronzeStock=12; PenRestMaker.woodStock=14; PenRestMaker.leatherStock=8; PenRestMaker.silverStock=8; PenRestMaker.goldStock=6; PenRestMaker.jewelStock=4; PenRestMaker.pearlStock=4; PenRestMaker.productStock={}; PenRestMaker.buildings={}; PenRestMaker.maker=nil; PenRestMaker.activeMaking={}; PenRestMaker.totalProducts=0; PenRestMaker.dayTimer=0; print("[PenRestMaker] Royal Pen Rest Maker System initialized (6 products, 4 buildings)") end
function PenRestMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PenRestMaker.maker={name=n or ("Počivalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Počivalec najet: %s (spretnost: %d)",PenRestMaker.maker.name,s),"success") end; return true end
function PenRestMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PenRestMaker.build(id) local ok,e=PenRestMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PenRestMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PenRestMaker.getQualityBonus() local b=0; for _,bd in ipairs(PenRestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PenRestMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PenRestMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PenRestMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PenRestMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PenRestMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PenRestMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PenRestMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PenRestMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PenRestMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PenRestMaker.buildings==0 then return false,"Potrebna počivalna delavnica" end; if not PenRestMaker.maker then return false,"Potreben počivalec" end; return true end
function PenRestMaker.make(pt,qty) qty=qty or 1; local ok,e=PenRestMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PenRestMaker.ironStock=PenRestMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PenRestMaker.bronzeStock=PenRestMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PenRestMaker.woodStock=PenRestMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PenRestMaker.leatherStock=PenRestMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PenRestMaker.silverStock=PenRestMaker.silverStock-d.silverCost*qty end; if d.goldCost then PenRestMaker.goldStock=PenRestMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PenRestMaker.jewelStock=PenRestMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PenRestMaker.pearlStock=PenRestMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PenRestMaker.maker then t=math.max(1,t-math.floor(PenRestMaker.maker.skill/13)) end; table.insert(PenRestMaker.activeMaking,{id="penrest_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PenRestMaker.completeMaking(m) local q=1.0+(PenRestMaker.getQualityBonus()/100); if PenRestMaker.maker then q=q+(PenRestMaker.maker.skill/140) end; q=math.min(2.5,q); PenRestMaker.productStock[m.productType]=(PenRestMaker.productStock[m.productType] or 0)+m.quantity; PenRestMaker.totalProducts=PenRestMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PenRestMaker.maker then PenRestMaker.maker.itemsMade=PenRestMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PenRestMaker.maker.skill=math.min(100,PenRestMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Počivališče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"penrest.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PenRestMaker.update(dt) if not _G.state then return end; PenRestMaker.dayTimer=PenRestMaker.dayTimer+dt; if PenRestMaker.dayTimer>=30 then PenRestMaker.dayTimer=0; for i=#PenRestMaker.activeMaking,1,-1 do local m=PenRestMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PenRestMaker.completeMaking(m); table.remove(PenRestMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PenRestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PenRestMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PenRestMaker.getStats() return {ironStock=PenRestMaker.ironStock,bronzeStock=PenRestMaker.bronzeStock,woodStock=PenRestMaker.woodStock,leatherStock=PenRestMaker.leatherStock,silverStock=PenRestMaker.silverStock,goldStock=PenRestMaker.goldStock,jewelStock=PenRestMaker.jewelStock,pearlStock=PenRestMaker.pearlStock,productStock=PenRestMaker.productStock,numBuildings=#PenRestMaker.buildings,hasMaker=PenRestMaker.maker~=nil,makerName=PenRestMaker.maker and PenRestMaker.maker.name or "—",makerSkill=PenRestMaker.maker and PenRestMaker.maker.skill or 0,activeMaking=#PenRestMaker.activeMaking,totalProducts=PenRestMaker.totalProducts} end
return PenRestMaker
